require __DIR__.'/../config/app.php';$me=require_role('admin');$view=$_GET['view']??'applications';$hoursView=$view==='hours';$opportunitiesView=$view==='opportunities';$action=(string)($_GET['action']??'');$search=trim((string)($_GET['q']??''));$editingOpportunity=$opportunitiesView&&in_array($action,['create','edit'],true);$opportunityId=(int)($_GET['id']??0);$opportunity=null;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$action=$_POST['action']??'';
