            $title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$date=(string)($_POST['event_date']??'');$venue=trim((string)($_POST['venue']??''));
            if($title===''||$date===''||$venue==='')throw new RuntimeException('Enter a title, date, and venue for this opportunity.');
            db()->prepare('INSERT INTO volunteer_opportunities(title,description,event_date,venue,created_by) VALUES(?,?,?,?,?)')->execute([$title,$description,$date,$venue,$me['id']]);flash('Volunteer opportunity created.');go('admin/volunteers.php?view=opportunities');
        }
