            $id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$date=(string)($_POST['event_date']??'');$venue=trim((string)($_POST['venue']??''));$validDate=DateTime::createFromFormat('Y-m-d',$date);
            if($title===''||mb_strlen($title)>190||!$validDate||$validDate->format('Y-m-d')!==$date||$venue===''||mb_strlen($venue)>190)throw new RuntimeException('Enter a valid opportunity name, date, and venue.');
            if($id){$q=db()->prepare('UPDATE volunteer_opportunities SET title=?,description=?,event_date=?,venue=? WHERE id=?');$q->execute([$title,$description,$date,$venue,$id]);$check=db()->prepare('SELECT id FROM volunteer_opportunities WHERE id=?');$check->execute([$id]);if(!$check->fetchColumn())throw new RuntimeException('Volunteer opportunity not found.');flash('Volunteer opportunity updated.');}
            else{db()->prepare('INSERT INTO volunteer_opportunities(title,description,event_date,venue,created_by) VALUES(?,?,?,?,?)')->execute([$title,$description,$date,$venue,$me['id']]);flash('Volunteer opportunity created.');}
            go('admin/volunteers.php?view=opportunities');
        }
