        if($action==='application_status'){
            $id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['Pending','Approved','Rejected'],true))throw new RuntimeException('Choose a valid application status.');
            $q=db()->prepare('SELECT a.user_id,o.title FROM volunteer_applications a JOIN volunteer_opportunities o ON o.id=a.opportunity_id WHERE a.id=?');$q->execute([$id]);$app=$q->fetch();if(!$app)throw new RuntimeException('Volunteer application not found.');
            db()->prepare('UPDATE volunteer_applications SET status=? WHERE id=?')->execute([$status,$id]);
            $notify=db()->prepare('INSERT INTO notifications(user_id,title,message) SELECT ?,?,? WHERE COALESCE((SELECT in_app_notifications FROM user_settings WHERE user_id=?),1)=1');$notify->execute([$app['user_id'],'Volunteer application updated',$app['title'].' application status is now '.$status.'.',$app['user_id']]);flash('Volunteer application status updated.');go('admin/volunteers.php');
        }
