        if($action==='save_hours'){$id=(int)($_POST['id']??0);$hours=filter_var($_POST['hours']??null,FILTER_VALIDATE_FLOAT);$notes=trim((string)($_POST['notes']??''));if(!$hours||$hours<0.25||$hours>500||mb_strlen($notes)>255)throw new RuntimeException('Enter hours between 0.25 and 500 and notes up to 255 characters.');db()->prepare('UPDATE volunteer_hours SET hours=?,notes=? WHERE id=?')->execute([$hours,$notes,$id]);flash('Volunteer hours updated.');go('admin/volunteers.php?view=hours');}
        if($action==='delete_hours'){$id=(int)($_POST['id']??0);$q=db()->prepare('DELETE FROM volunteer_hours WHERE id=?');$q->execute([$id]);flash($q->rowCount()?'Volunteer hours record deleted.':'Hours record not found.');go('admin/volunteers.php?view=hours');}
        throw new RuntimeException('Unknown volunteer action.');
    }catch(Throwable $t){$error=$t instanceof RuntimeException?$t->getMessage():'Could not save the volunteer update.';if(($action??'')==='save_opportunity'){$editingOpportunity=true;$opportunity=['id'=>(int)($_POST['id']??0),'title'=>$title??'','description'=>$description??'','event_date'=>$date??'','venue'=>$venue??''];}}
}
$formErrorData=[];
if($editingOpportunity&&$action==='edit'&&$opportunityId){try{$q=db()->prepare('SELECT * FROM volunteer_opportunities WHERE id=?');$q->execute([$opportunityId]);$opportunity=$q->fetch();if(!$opportunity){flash('Opportunity not found.','error');go('admin/volunteers.php?view=opportunities');}}catch(Throwable $t){$error='Could not load the opportunity.';}}
$rows=[];$summary=['volunteers'=>0,'applications'=>0,'hours'=>0,'opportunities'=>0];
try{$summary['volunteers']=(int)db()->query("SELECT COUNT(DISTINCT user_id) FROM volunteer_applications WHERE status='Approved'")->fetchColumn();$summary['applications']=(int)db()->query('SELECT COUNT(*) FROM volunteer_applications')->fetchColumn();$summary['hours']=(float)db()->query('SELECT COALESCE(SUM(hours),0) FROM volunteer_hours')->fetchColumn();$summary['opportunities']=(int)db()->query('SELECT COUNT(*) FROM volunteer_opportunities')->fetchColumn();
    if($hoursView){$q=db()->prepare('SELECT h.id,h.hours,h.notes,h.is_verified,h.recorded_at,u.name,u.email,o.title opportunity FROM volunteer_hours h JOIN users u ON u.id=h.user_id LEFT JOIN volunteer_opportunities o ON o.id=h.opportunity_id WHERE (?=\'\' OR u.name LIKE ? OR u.email LIKE ? OR o.title LIKE ?) ORDER BY h.recorded_at DESC');$term='%'.$search.'%';$q->execute([$search,$term,$term,$term]);$rows=$q->fetchAll();}
    elseif($opportunitiesView){$q=db()->prepare('SELECT o.id,o.title,o.description,o.event_date,o.venue,COUNT(a.id) applications FROM volunteer_opportunities o LEFT JOIN volunteer_applications a ON a.opportunity_id=o.id WHERE (?=\'\' OR o.title LIKE ? OR o.venue LIKE ?) GROUP BY o.id ORDER BY o.event_date');$term='%'.$search.'%';$q->execute([$search,$term,$term]);$rows=$q->fetchAll();}
    else{$q=db()->prepare('SELECT a.id,a.status,a.created_at,u.name,u.email,o.title opportunity,o.event_date,o.venue FROM volunteer_applications a JOIN users u ON u.id=a.user_id JOIN volunteer_opportunities o ON o.id=a.opportunity_id WHERE (?=\'\' OR u.name LIKE ? OR u.email LIKE ? OR o.title LIKE ?) ORDER BY a.created_at DESC');$term='%'.$search.'%';$q->execute([$search,$term,$term,$term]);$rows=$q->fetchAll();}
}catch(Throwable $t){}
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="eventhub-volunteers-'.date('Ymd').'.csv"');$out=fopen('php://output','w');if($hoursView){fputcsv($out,['Student','Email','Opportunity','Hours','Notes','Verified','Recorded']);foreach($rows as $r)fputcsv($out,[$r['name'],$r['email'],$r['opportunity'],$r['hours'],$r['notes'],$r['is_verified']?'Yes':'No',$r['recorded_at']]);}elseif($opportunitiesView){fputcsv($out,['Opportunity','Date','Venue','Applications']);foreach($rows as $r)fputcsv($out,[$r['title'],$r['event_date'],$r['venue'],$r['applications']]);}else{fputcsv($out,['Student','Email','Opportunity','Date','Venue','Applied','Status']);foreach($rows as $r)fputcsv($out,[$r['name'],$r['email'],$r['opportunity'],$r['event_date'],$r['venue'],$r['created_at'],$r['status']]);}fclose($out);exit;}
$perPage=25;$totalRecords=count($rows);$totalPages=(int)ceil($totalRecords/$perPage);$currentPage=max(1,min($totalPages?:1,(int)($_GET['page']??1)));$rows=array_slice($rows,($currentPage-1)*$perPage,$perPage);$pageTitle=$hoursView?'Verify Volunteer Hours':($opportunitiesView?'Manage Volunteer Opportunities':'Manage Volunteers');$bodyClass='dashboard-page admin-page';$activePage='volunteers';$adminSection='volunteers';require __DIR__.'/../includes/header.php';
