"id" value="<?=$r['id']?>"><input type="hidden" name="verified" value="<?=$r['is_verified']?0:1?>"><button class="text-button" type="submit"><?=$r['is_verified']?'Unverify':'Verify'?></button></form><form method="post" onsubmit="return confirm('Delete these recorded hours?')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete_hours"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-button danger-text" type="submit">Delete</button></form></div></td><?php else:?><td><?=date('d M Y',strtotime($r['event_date']))?></td><td><?=e($r['venue'])?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="application_status"><input type="hidden" name="id" value="<?=$r['id']?>"><select class="application-status" name="status" onchange="this.form.submit()" aria-label="Application status for <?=e($r['name'])?>"><?php foreach(['Pending','Approved','Rejected'] as $status):?><option <?=$r['status']===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty"><?=$hoursView?'No volunteer hours have been submitted yet.':'Student applications will appear here after they apply to an opportunity.'?></div><?php endif;?></section><?php endif;?><?php if(!$editingOpportunity)require __DIR__.'/../includes/admin-pagination.php';?></main></div><?php require __DIR__.'/../includes/footer.php';
